@startuml

class Driver {
  + ID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

class Schedule {
  + Date : date
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class CityStaff {}

CityStaff "1" -- "*" Route : determines
CityStaff "1" -- "*" Bus : assigns
CityStaff "1" -- "*" Driver : schedules

Route "1" -- "*" Bus : "assigned to"
Bus "1" -- "*" Route : "serves"

Schedule "1" -- "*" Shift : "contains"
Shift "1" -- "1" Driver : "assigned to"
Shift "1" -- "1" Bus : "assigned to"
Shift "1" -- "1" Route : "belongs to"

@enduml

